//! JSON API of the `posts` resource, generated by
//! `forge generate resource` (and `forge generate scaffold`). Handlers stay
//! thin: authorize, decode the request, call [`PostService`], answer
//! JSON.
//!
//! | Method | Path | Action | Permission |
//! | --- | --- | --- | --- |
//! | `GET` | `/v1/posts?cursor=ID` | list, in creation order, `PAGE_SIZE` per page | `posts:read` |
//! | `POST` | `/v1/posts` | create: `201` with `Location` | `posts:write` |
//! | `GET` | `/v1/posts/{id}` | show | `posts:read` |
//! | `PATCH` | `/v1/posts/{id}` | change the members sent, with the `version` read | `posts:write` |
//! | `DELETE` | `/v1/posts/{id}?version=N` | delete the version read: `204` | `posts:write` |
//!
//! A stale `version` answers `409`, an invalid value `422` with a message
//! per member in `metadata`, an unknown `{id}` `404`. `PATCH` changes only
//! the members it names; `null` clears an optional one. Every route is
//! described in the OpenAPI document (`GET /openapi.json`, `forge openapi`).

use std::future::Future;
use std::sync::Arc;

use forge::ComposeError;
use forge::core::{ErrorCategory, ForgeError, Version};
use forge::http::{HeaderValue, Method, Request, Response, Router, StatusCode, header};
use forge::openapi::{OpenApiSchema, Operation, Param, describe};
use forge::security::Permission;
use forge::web::Patch;
use serde::{Deserialize, Serialize};

use crate::adapters::http::api_access::ApiGlobalAccess;
use crate::application::use_cases::posts::{
    PostError, PostService, READ_PERMISSION, WRITE_PERMISSION,
};
use crate::domain::entities::post::{Post, PostAttributes, PostId};

/// The collection's path.
pub const COLLECTION_PATH: &str = "/v1/posts";

/// A post as the API answers it.
#[derive(Debug, Serialize, OpenApiSchema)]
pub struct PostJson {
    /// The post's UUIDv7.
    pub id: PostId,
    pub title: String,
    pub body: String,
    pub published: bool,
    /// The optimistic-locking version: `PATCH` and `DELETE` send it back.
    pub version: i64,
}

impl From<&Post> for PostJson {
    fn from(post: &Post) -> Self {
        let PostAttributes {
            title,
            body,
            published,
        } = post.attributes().clone();
        Self {
            id: post.id(),
            title,
            body,
            published,
            version: post.version().get(),
        }
    }
}

/// One page of posts.
#[derive(Debug, Serialize, OpenApiSchema)]
pub struct PostList {
    pub items: Vec<PostJson>,
    /// The `cursor` of the next page; `null` on the last one.
    pub next_cursor: Option<PostId>,
}

/// The body of `POST`: every required member.
#[derive(Debug, Deserialize, OpenApiSchema)]
pub struct NewPost {
    pub title: String,
    pub body: String,
    pub published: bool,
}

impl From<NewPost> for PostAttributes {
    fn from(body: NewPost) -> Self {
        let NewPost {
            title,
            body,
            published,
        } = body;
        Self {
            title,
            body,
            published,
        }
    }
}

/// The body of `PATCH`: the version read and the members to change. A member
/// left out stays as it is; `null` clears an optional one.
#[derive(Debug, Deserialize, OpenApiSchema)]
pub struct PostChanges {
    /// The version the client last read.
    pub version: i64,
    #[serde(default, skip_serializing_if = "Patch::is_absent")]
    pub title: Patch<String>,
    #[serde(default, skip_serializing_if = "Patch::is_absent")]
    pub body: Patch<String>,
    #[serde(default, skip_serializing_if = "Patch::is_absent")]
    pub published: Patch<bool>,
}

impl PostChanges {
    /// Applies the members sent to `attributes`; `null` for a required
    /// member is refused.
    fn apply(self, attributes: &mut PostAttributes) -> Result<(), ForgeError> {
        match self.title {
            Patch::Absent => {}
            Patch::Null => return Err(not_null("title")),
            Patch::Value(value) => attributes.title = value,
        }
        match self.body {
            Patch::Absent => {}
            Patch::Null => return Err(not_null("body")),
            Patch::Value(value) => attributes.body = value,
        }
        match self.published {
            Patch::Absent => {}
            Patch::Null => return Err(not_null("published")),
            Patch::Value(value) => attributes.published = value,
        }
        Ok(())
    }
}

/// The query of `GET /v1/posts`.
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct ListQuery {
    cursor: Option<PostId>,
}

/// The query of `DELETE`: the version the client last read.
#[derive(Deserialize)]
#[serde(deny_unknown_fields)]
struct DeleteQuery {
    version: i64,
}

/// What every handler shares.
struct PostApi {
    service: PostService,
    access: Arc<dyn ApiGlobalAccess>,
    read: Permission,
    write: Permission,
}

/// Registers the routes. `access` decides who may call them (see
/// `crate::adapters::http::api_access`); nothing is served before it agrees.
pub fn routes(
    router: &mut Router,
    service: PostService,
    access: Arc<dyn ApiGlobalAccess>,
) -> Result<(), ComposeError> {
    let state = Arc::new(PostApi {
        service,
        access,
        read: Permission::new(READ_PERMISSION).map_err(ComposeError::other)?,
        write: Permission::new(WRITE_PERMISSION).map_err(ComposeError::other)?,
    });
    let member = format!("{COLLECTION_PATH}/{{id}}");
    let id = || Param::path::<PostId>("id").doc("The post's ID.");
    route(
        router,
        &state,
        Method::GET,
        COLLECTION_PATH,
        list,
        operation(
            "listPosts",
            "List posts, in creation order",
            READ_PERMISSION,
        )
        .param(
            Param::query::<Option<PostId>>("cursor").doc("The next_cursor of the previous page."),
        )
        .json::<PostList>(200)
        .errors([422]),
    )?;
    route(
        router,
        &state,
        Method::POST,
        COLLECTION_PATH,
        create,
        operation("createPost", "Create a post", WRITE_PERMISSION)
            .request::<NewPost>()
            .response(forge::openapi::Response::json::<PostJson>(201).header("Location")),
    )?;
    route(
        router,
        &state,
        Method::GET,
        &member,
        show,
        operation("getPost", "Get a post", READ_PERMISSION)
            .param(id())
            .json::<PostJson>(200)
            .errors([400, 404]),
    )?;
    route(
        router,
        &state,
        Method::PATCH,
        &member,
        update,
        operation(
            "updatePost",
            "Change some members of a post",
            WRITE_PERMISSION,
        )
        .param(id())
        .request::<PostChanges>()
        .json::<PostJson>(200)
        .errors([400, 404, 409]),
    )?;
    route(
        router,
        &state,
        Method::DELETE,
        &member,
        destroy,
        operation("deletePost", "Delete a post", WRITE_PERMISSION)
            .param(id())
            .param(
                Param::query::<i64>("version")
                    .required()
                    .doc("The version the client last read."),
            )
            .response(forge::openapi::Response::empty(204))
            .errors([400, 404, 409, 422]),
    )?;
    Ok(())
}

/// The description every route shares: bearer authentication, the
/// permission and the access policy's `503`.
fn operation(id: &str, summary: &str, permission: &str) -> Operation {
    Operation::new()
        .id(id)
        .summary(summary)
        .tag("posts")
        .bearer()
        .permission(permission)
        .errors([503])
}

fn route<H, F>(
    router: &mut Router,
    state: &Arc<PostApi>,
    method: Method,
    path: &str,
    handler: H,
    operation: Operation,
) -> Result<(), ComposeError>
where
    H: Fn(Arc<PostApi>, Request) -> F + Send + Sync + 'static,
    F: Future<Output = Response> + Send + 'static,
{
    let state = Arc::clone(state);
    router.route(
        method,
        path,
        describe(
            move |request: Request| handler(Arc::clone(&state), request),
            operation,
        ),
    )?;
    Ok(())
}

async fn list(state: Arc<PostApi>, request: Request) -> Response {
    if let Err(denied) = state.access.authorize(&request, &state.read).await {
        return forge::web::bearer_refusal(denied);
    }
    let query: ListQuery = match forge::web::decode_query(&request) {
        Ok(query) => query,
        Err(failure) => return forge::web::error(&failure),
    };
    match state.service.list(query.cursor).await {
        Ok(page) => forge::web::json(
            StatusCode::OK,
            &PostList {
                items: page.posts.iter().map(PostJson::from).collect(),
                next_cursor: page.next,
            },
        ),
        Err(error) => failure(error),
    }
}

async fn create(state: Arc<PostApi>, request: Request) -> Response {
    if let Err(denied) = state.access.authorize(&request, &state.write).await {
        return forge::web::bearer_refusal(denied);
    }
    let body: NewPost = match forge::web::decode_json_strict(&request) {
        Ok(body) => body,
        Err(failure) => return forge::web::error(&failure),
    };
    match state.service.create(body.into()).await {
        Ok(post) => {
            let mut response = forge::web::json(StatusCode::CREATED, &PostJson::from(&post));
            if let Ok(location) = HeaderValue::from_str(&format!("{COLLECTION_PATH}/{}", post.id()))
            {
                response.headers_mut().insert(header::LOCATION, location);
            }
            response
        }
        Err(error) => failure(error),
    }
}

async fn show(state: Arc<PostApi>, request: Request) -> Response {
    if let Err(denied) = state.access.authorize(&request, &state.read).await {
        return forge::web::bearer_refusal(denied);
    }
    let Some(id) = path_id(&request) else {
        return invalid_id();
    };
    match state.service.find(id).await {
        Ok(post) => forge::web::json(StatusCode::OK, &PostJson::from(&post)),
        Err(error) => failure(error),
    }
}

async fn update(state: Arc<PostApi>, request: Request) -> Response {
    if let Err(denied) = state.access.authorize(&request, &state.write).await {
        return forge::web::bearer_refusal(denied);
    }
    let Some(id) = path_id(&request) else {
        return invalid_id();
    };
    let changes: PostChanges = match forge::web::decode_json_strict(&request) {
        Ok(changes) => changes,
        Err(failure) => return forge::web::error(&failure),
    };
    let expected = match Version::new(changes.version) {
        Ok(expected) => expected,
        Err(failure) => return forge::web::error(&failure),
    };
    // The stored attributes with the members sent; the update itself checks
    // that the version read is still the stored one.
    let mut attributes = match state.service.find(id).await {
        Ok(post) => post.attributes().clone(),
        Err(error) => return failure(error),
    };
    if let Err(failure) = changes.apply(&mut attributes) {
        return forge::web::error(&failure);
    }
    match state.service.update(id, expected, attributes).await {
        Ok(post) => forge::web::json(StatusCode::OK, &PostJson::from(&post)),
        Err(error) => failure(error),
    }
}

async fn destroy(state: Arc<PostApi>, request: Request) -> Response {
    if let Err(denied) = state.access.authorize(&request, &state.write).await {
        return forge::web::bearer_refusal(denied);
    }
    let Some(id) = path_id(&request) else {
        return invalid_id();
    };
    let expected = match forge::web::decode_query::<DeleteQuery>(&request)
        .and_then(|query| Version::new(query.version))
    {
        Ok(expected) => expected,
        Err(failure) => return forge::web::error(&failure),
    };
    match state.service.delete(id, expected).await {
        Ok(()) => Response::empty(StatusCode::NO_CONTENT),
        Err(error) => failure(error),
    }
}

/// The route's `{id}`, when it is a UUIDv7.
fn path_id(request: &Request) -> Option<PostId> {
    request.path_param_as("id").ok()
}

/// `400 invalid_id`: the `{id}` is not a UUIDv7.
fn invalid_id() -> Response {
    let failure = ForgeError::new(
        ErrorCategory::Validation,
        "invalid_id",
        "the post ID is not a UUIDv7",
    );
    forge::web::json(StatusCode::BAD_REQUEST, &failure.report())
}

/// The JSON answer to a failed use case.
fn failure(error: PostError) -> Response {
    match error {
        PostError::Invalid(violations) => {
            let mut failure = ForgeError::new(
                ErrorCategory::Validation,
                "validation_failed",
                "the post is invalid",
            );
            for (field, violation) in violations.iter() {
                failure = failure.with_metadata(field.name(), violation.to_string());
            }
            forge::web::error(&failure)
        }
        PostError::NotFound => forge::web::error(&ForgeError::new(
            ErrorCategory::NotFound,
            "post_not_found",
            "post not found",
        )),
        PostError::Conflict => forge::web::error(&ForgeError::new(
            ErrorCategory::Conflict,
            "post_conflict",
            "the post was changed by someone else",
        )),
        // Logged with its cause chain; the client sees a generic report.
        PostError::Store(error) => forge::web::error(
            &ForgeError::new(
                ErrorCategory::Infrastructure,
                "post_storage_failed",
                "service temporarily unavailable",
            )
            .with_source(error),
        ),
    }
}

/// `null` for a member that cannot be empty.
fn not_null(member: &str) -> ForgeError {
    ForgeError::new(
        ErrorCategory::Validation,
        "validation_failed",
        "the post is invalid",
    )
    .with_metadata(member, "can't be null")
}
